function reviewCard(s,id,index){const asset=usableAssets(s).find(item=>Number(item.assetId)===Number(id));return asset?`<article class="bew-review-card">${overlayPreviewMarkup(s,id,false)}<b>${index+1}. ${esc(assetTitle(asset))}</b></article>`:''}
