function renderResultNotice(s){const root=$('[data-bew-result-notice]',s.root);if(!root)return;const notice=s.resultNotice;if(!notice){root.hidden=true;return}root.hidden=false;const title=$('[data-bew-result-title]',root),copy=$('[data-bew-result-copy]',root);if(title)title.textContent=`'${notice.name}' 게시를 확인했습니다.`;if(copy)copy.textContent=`이벤트 식별자 ${notice.eventGroupId}${notice.detail?` · ${notice.detail}`:''} · 작성 화면은 새 이벤트를 만들 수 있도록 초기화했습니다.`}
function hasWorkflowContent(s){return Boolean(String(s.bundleName||'').trim()||s.selected.length||Object.values(s.overlays).some(layers=>Array.isArray(layers)&&layers.length))}
function hasResettableContent(s){return Boolean(hasWorkflowContent(s)||s.files.length||s.uploadTags.length||s.overlayUploadFile||s.eventGroupId||s.dirty||String($('[data-bew-tag-input]',s.root)?.value||'').trim())}
