function clearDraftData(s,{resultNotice=null}={}){releaseDraftUrls(s);const mainCode=s.kind==='main'?String(s.targetContract?.main?.pageCode||''):'';Object.assign(s,{busy:false,files:[],uploadTags:[],tagError:'',tagComposing:false,overlayUploadFile:null,overlayUploadName:'',overlayUploadKind:'STICKER',overlayUploadAddNow:true,overlayUploadStatus:'',overlayUploadStatusKind:'',stickerPanelOpen:false,emojiPopoverOpen:false,emojiQuery:'',selected:[],filter:'NONE',libraryVisible:WINDOW_SIZE,orderVisible:WINDOW_SIZE,overlayPage:0,reviewVisible:12,replaceIndex:null,bundleName:'',targetPages:mainCode?[mainCode]:[],individualTargetPages:[],allPagesSelected:false,sideMode:'SYNC',variants:variantSet(),assignments:{left:[],right:[]},assignmentsInitialized:false,overlays:{},overlayTarget:0,overlayLayerIndex:0,overlayApply:[],eventGroupId:null,savedEvent:null,published:false,dirty:false,activeStep:1,validationAttempted:false,resetOpen:false,resetReturnFocus:null,resultNotice})}
