async function saveDraft(s,{quiet=false}={}){if(!String(s.bundleName||'').trim()){focusIssue(s,{step:2,selector:'[data-bew-bundle-name]',message:'초안을 저장하려면 이벤트 이름을 입력해 주세요.'});return null}if(!s.targetContract){focusIssue(s,{step:3,selector:'[data-bew-settings]',message:'서버의 노출 페이지 목록을 확인한 뒤 초안을 저장해 주세요.'});return null}if(s.busy)return null;s.busy=true;renderActions(s);if(!quiet)actionNote(s,'초안을 저장하는 중...');try{const result=await api(s,'event-save',{eventGroupId:s.eventGroupId,event:eventPayload(s)},true);s.eventGroupId=String(result.eventGroupId||s.eventGroupId||'');s.savedEvent=result.event||null;s.dirty=false;if(!quiet)actionNote(s,'진행 중인 초안을 저장했습니다.','ok');return result}catch(error){actionNote(s,error.message||String(error),'error');return null}finally{s.busy=false;renderActions(s)}}
function loadCanvasImage(url){return new Promise((resolve,reject)=>{const image=new Image();image.crossOrigin='anonymous';image.onload=()=>resolve(image);image.onerror=()=>reject(Error('합성에 필요한 이미지를 불러오지 못했습니다.'));image.src=url})}
