async function drawContentLayer(ctx,s,layer,width,height){if(layer.enabled===false)return;ctx.save();ctx.globalAlpha=Math.max(0,Math.min(100,Number(layer.opacity??100)))/100;if(layer.type==='TEXT'){if(!String(layer.text||'').trim()){ctx.restore();return}const stripHeight=height*Math.max(6,Math.min(60,Number(layer.heightPercent)||18))/100,y=layer.verticalPosition==='TOP'?0:layer.verticalPosition==='MIDDLE'?(height-stripHeight)/2:height-stripHeight;ctx.translate(width/2,y+stripHeight/2);ctx.rotate((Number(layer.rotationDeg)||0)*Math.PI/180);ctx.fillStyle=overlayRgba(layer.backgroundColor,layer.backgroundOpacity);ctx.fillRect(-width/2,-stripHeight/2,width,stripHeight);ctx.fillStyle=layer.textColor||'#FFFFFF';ctx.font=`${Math.max(10,Math.min(96,Number(layer.fontSizePx)||18))}px ${overlayFont(layer.fontFamily)}`;ctx.textAlign='center';ctx.textBaseline='middle';const lines=textLines(ctx,layer.text,width-24),lineHeight=Math.max(12,Math.min(108,(Number(layer.fontSizePx)||18)*1.25)),start=-(lines.length-1)*lineHeight/2;lines.forEach((line,index)=>ctx.fillText(line,0,start+index*lineHeight,width-24));ctx.restore();return}
  const x=width*positionPercent(layer.horizontalPosition)/100,y=height*positionPercent(layer.verticalPosition)/100,size=width*Math.max(5,Math.min(60,Number(layer.sizePercent)||24))/100;ctx.translate(x,y);ctx.rotate((Number(layer.rotationDeg)||0)*Math.PI/180);if(layer.type==='EMOJI'){if(String(layer.emoji||'').trim()){ctx.font=`${Math.max(12,size)}px ${overlayFont('SYSTEM_SANS')}`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(layer.emoji,0,0)}ctx.restore();return}const asset=overlayAssetById(s,layer.overlayAssetId);if(asset?.imageUrl){const image=await loadCanvasImage(asset.imageUrl),scale=Math.min(size/image.naturalWidth,size/image.naturalHeight),w=image.naturalWidth*scale,h=image.naturalHeight*scale;ctx.drawImage(image,-w/2,-h/2,w,h)}ctx.restore()}
async function compositeBlob(s,id){const asset=usableAssets(s).find(item=>Number(item.assetId)===Number(id));if(!asset)throw Error('합성할 원본 이미지를 찾지 못했습니다.');const canvas=document.createElement('canvas');canvas.width=s.config.width;canvas.height=s.config.height;const ctx=canvas.getContext('2d');if(!ctx)throw Error('브라우저 이미지 합성 기능을 사용할 수 없습니다.');const layers=overlayLayers(s,id);for(const layer of layers.filter(item=>item.layerPosition==='BACK'))await drawContentLayer(ctx,s,layer,canvas.width,canvas.height);drawCover(ctx,await loadCanvasImage(assetUrl(s,asset)),canvas.width,canvas.height);for(const layer of layers.filter(item=>item.layerPosition!=='BACK'))await drawContentLayer(ctx,s,layer,canvas.width,canvas.height);return new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(Error('게시용 합성 이미지를 만들지 못했습니다.')),'image/webp',.92))}
