async function publishWorkflow(s){const issue=validatePublish(s);if(issue){focusIssue(s,issue);return}s.activeStep=5;s.validationAttempted=false;renderActions(s);const saved=await saveDraft(s,{quiet:true});if(!saved)return;s.busy=true;renderActions(s);try{const ids=[...new Set(eventPayload(s).variants.flatMap(variant=>variant.items.map(item=>Number(item.assetId))))].filter(id=>overlayLayers(s,id).some(layer=>layer.enabled!==false)),eventName=String(s.bundleName||'').trim(),eventGroupId=String(s.eventGroupId||'');for(let index=0;index<ids.length;index++){const blob=await compositeBlob(s,ids[index]);if(blob.size>MAX_BYTES)throw Error('합성 이미지가 5MB를 초과했습니다. 콘텐츠 수나 원본 복잡도를 줄여 주세요.');await uploadComposite(s,ids[index],blob,index+1,ids.length)}actionNote(s,'전체 이벤트를 게시하는 중...');const result=await api(s,'event-publish',{eventGroupId},true);s.savedEvent=result.event||s.savedEvent;s.dirty=false;actionNote(s,'게시 결과를 서버에서 다시 확인하는 중...');const readback=await api(s,'event-list',{includeArchived:true}),confirmed=Array.isArray(readback.events)?readback.events.find(event=>String(event.eventGroupId||'')===eventGroupId):null;if(!confirmed||!['PUBLISHED','MIXED'].includes(String(confirmed.status||'')))throw Error('게시 요청은 처리됐지만 서버 게시 결과를 다시 확인하지 못했습니다. 작성 내용은 유지했습니다.');s.published=true;s.busy=false;resetWorkflow(s,{resultNotice:{name:String(confirmed.name||eventName),eventGroupId,detail:`합성 이미지 ${ids.length}장 저장`}})}catch(error){s.published=false;actionNote(s,error.message||String(error),'error')}finally{s.busy=false;renderActions(s)}}

