function imagePeek(){let box=$('#bewImagePeek');if(box)return box;box=document.createElement('div');box.id='bewImagePeek';box.className='bew-image-peek';box.setAttribute('role','presentation');box.innerHTML='<img alt="확대 미리보기">';document.body.appendChild(box);return box}
